from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    outside = [[False]*w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0,w-1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True; q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True; q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and not outside[nr][nc]:
                outside[nr][nc]=True; q.append((nr,nc))
    inside = [[grid[r][c]==0 and not outside[r][c] for c in range(w)] for r in range(h)]
    # Interior boundary layer.
    for r in range(h):
        for c in range(w):
            if inside[r][c] and any(0<=r+dr<h and 0<=c+dc<w and grid[r+dr][c+dc]==1
                                      for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc):
                out[r][c]=3
    # Find 8-connected wall components; only components enclosing a cavity get an exterior halo.
    seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=1 or (r,c) in seen: continue
            comp=[]; q=deque([(r,c)]); seen.add((r,c)); has_inside=False
            while q:
                rr,cc=q.popleft(); comp.append((rr,cc))
                for dr in (-1,0,1):
                    for dc in (-1,0,1):
                        if not (dr or dc): continue
                        nr,nc=rr+dr,cc+dc
                        if 0<=nr<h and 0<=nc<w:
                            if inside[nr][nc]: has_inside=True
                            if grid[nr][nc]==1 and (nr,nc) not in seen:
                                seen.add((nr,nc));q.append((nr,nc))
            if has_inside:
                for rr,cc in comp:
                    for dr in (-1,0,1):
                        for dc in (-1,0,1):
                            nr,nc=rr+dr,cc+dc
                            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and outside[nr][nc]:
                                out[nr][nc]=2
    return out

